    }
    | {
        event: AgentConversationEventEntry
        kind: 'agentEvent'
    }
    | {
        command?: string
        content: string
        kind: 'error' | 'output'
        messageId?: string
        previousContent?: string
        replace?: boolean
        sequence?: number
    }

export type ActionRunEvent =
    | ActionRunEventBase & {
        status: ActionRunStatus
        type: 'run'
    }
    | ActionRunEventBase & {
        command?: string
        conversationId?: string
        runWorktree?: number | null
        message?: string | null
        accessLevel?: string
        approvalPolicy?: string
        reference?: string
        status: ActionRunStatus
        thinkingLevel?: ThinkingLevel
        type: 'action'
    }
    | ActionRunEventBase & {
        status: 'running' | 'waitingForInput'
        type: 'agentState'
    }
    | ActionRunEventBase & {
        status: ActionRunStatus
        type: 'update'
        update: ActionRunUpdate
    }

