    accessLevel?: string
    actionId: string
    actionName: string
    approvalPolicy?: string
    command: string | null
    message: string
    phase: ActionRunPhase
    status: ActionRunStatus
    stderr: string
    stdout: string
    thinkingLevel?: ThinkingLevel
}

export interface ActionRunResult {
    logs: ActionRunLogEntry[]
    status: ActionRunStatus
}

