import { ACTION_PROMPT_PLACEHOLDERS } from '../../data/action_placeholders'
import { MarkdownPlaceholderToolbarControl } from './markdown_placeholder_toolbar_control'

describe('MarkdownPlaceholderToolbarControl', () => {
    afterEach(() => {
        cleanup()
        vi.restoreAllMocks()
    })

    it('inserts the selected placeholder and returns focus to the editor', () => {
        const activeEditor = { dispatchCommand: vi.fn(), focus: vi.fn() }
        vi.spyOn(mdxEditor, 'useCellValue').mockReturnValue(activeEditor as never)
        render(<MarkdownPlaceholderToolbarControl placeholders={ACTION_PROMPT_PLACEHOLDERS} />)

        fireEvent.click(screen.getByRole('button', { name: 'Insert placeholder' }))
        const menu = screen.getByRole('menu')
        fireEvent.click(within(menu).getByRole('menuitem', { name: /card-file/u }))

        expect(activeEditor.dispatchCommand).toHaveBeenCalledExactlyOnceWith(
            CONTROLLED_TEXT_INSERTION_COMMAND,
            '{{card-file}}',
        )
        expect(activeEditor.focus).toHaveBeenCalledOnce()
        expect(screen.queryByRole('menu')).not.toBeInTheDocument()
    })

    it('offers all folder placeholders without the removed root placeholder', () => {
        vi.spyOn(mdxEditor, 'useCellValue').mockReturnValue({ dispatchCommand: vi.fn(), focus: vi.fn() } as never)
        render(<MarkdownPlaceholderToolbarControl placeholders={ACTION_PROMPT_PLACEHOLDERS} />)

        fireEvent.click(screen.getByRole('button', { name: 'Insert placeholder' }))

        const menu = within(screen.getByRole('menu'))
        expect(menu.getByRole('menuitem', { name: /worktree-folder/u })).toBeInTheDocument()
        expect(menu.getByRole('menuitem', { name: /project-folder/u })).toBeInTheDocument()
        expect(menu.getByRole('menuitem', { name: /releases-folder/u })).toBeInTheDocument()
        expect(menu.queryByRole('menuitem', { name: /rootProjectFolder/u })).not.toBeInTheDocument()
    })
})

# Placeholders

{% raw %}

Placeholders let one action definition work for every card. They are written as `{{name}}` and resolved on the desktop side, just before the process starts.

| Placeholder | Resolves to |
| --- | --- |
| `{{card-file}}` | Path to the selected card's Markdown file. |
| `{{card-title}}` | Title of the selected card. |
| `{{card-prompt}}` | The extra text you typed in the action popup for this run. |
| `{{worktree-folder}}` | Absolute path to the action execution checkout. |
| `{{project-folder}}` | Absolute path to the opened repository. |
| `{{releases-folder}}` | Absolute path to the configured releases folder under the opened repository. |

They work in both `prompt` (agent actions) and `command` (command actions).

## Using them

In the prompt editor, type `{{` for a typeahead list, or insert one from the toolbar.

```json
{
  "id": "fix-bug",
  "label": "Fix bug",
  "description": "Fix the bug described on the card",
  "type": "agent",
  "prompt": "Fix the bug described in {{card-file}}.\n\nExtra instructions: {{card-prompt}}"
}
```

```json
{
  "id": "open-in-editor",
  "label": "Open in VS Code",
  "description": "Open the card file in VS Code",
  "type": "command",
  "command": "code {{card-file}}"
}
```

## Notes

- A card placeholder only resolves when the action runs with card context. Use `appliesTo` with `"kind": "card"` so an action that needs `{{card-file}}` is only offered where it makes sense.
- `{{card-prompt}}` is empty when you run without typing anything. Write prompts that read fine either way.
- The diff command in project configuration supports the same three folder placeholders plus `{{commit}}`, `{{branch}}`, and `{{file}}`. For diffs, `{{worktree-folder}}` and `{{project-folder}}` both resolve to the opened repository.
- Custom agent profiles support `{{model}}` in `command` and `{{sessionId}}` in `resumeCommand`. Those are profile placeholders, not action placeholders.

{% endraw %}

See also: [Action definition](action-definition.md), [Cookbook](cookbook.md).

